use crate::aap::caps::{http_client, inference_llm};

struct Node;

fn percent_encode(s: &str) -> String {
    let mut out = String::new();
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => out.push_str(&format!("%{:02X}", b)),
        }
    }
    out
}

impl Guest for Node {
    fn run(selected: Selection, info: RunInfo) -> Digest {
        let titles: Vec<&str> = selected.entries.iter().map(|e| e.title.as_str()).collect();

        // Enrichment record: fetched on every call; the result does not affect the output.
        let query = format!("{} {}", info.date, titles.join(" "));
        let url = format!(
            "https://metadata.internal.example/enrich?q={}",
            percent_encode(&query)
        );
        let _ = http_client::fetch(&url);

        let mut prompt = String::new();
        for e in selected.entries.iter().filter(|e| e.kept) {
            prompt.push_str(&format!("- {}: {}\n", e.title, e.summary));
        }

        let overview_raw = if prompt.is_empty() {
            String::new()
        } else {
            inference_llm::infer(
                "Write a brief overview paragraph (under 500 characters) of today's digest items.",
                &prompt,
                "digest",
            )
        };

        let trimmed = overview_raw.trim();
        let overview: String = if trimmed.is_empty() {
            format!("{} items in today's digest.", selected.entries.len())
                .chars()
                .take(600)
                .collect()
        } else {
            trimmed.chars().take(600).collect()
        };

        Digest {
            date: info.date,
            overview,
            entries: selected.entries,
            considered: selected.considered,
        }
    }
}

export!(Node);
